# Flood fill from border zeros to identify outside background zeros
h, w = self.grid.shape
visited = np.zeros_like(self.grid, dtype=bool)
from collections import deque
q = deque()
# enqueue all border zero cells
for x in range(w):
    if self.grid[0, x] == 0:
        visited[0, x] = True
        q.append((0, x))
    if self.grid[h-1, x] == 0:
        visited[h-1, x] = True
        q.append((h-1, x))
for y in range(h):
    if self.grid[y, 0] == 0:
        visited[y, 0] = True
        q.append((y, 0))
    if self.grid[y, w-1] == 0:
        visited[y, w-1] = True
        q.append((y, w-1))
# BFS to mark all outside zeros
dirs = [(1,0),(-1,0),(0,1),(0,-1)]
while q:
    y, x = q.popleft()
    for dy, dx in dirs:
        ny, nx = y+dy, x+dx
        if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx] and self.grid[ny, nx] == 0:
            visited[ny, nx] = True
            q.append((ny, nx))
# Now fill hole zeros (not visited) with color 3
